export type MoneyEvent={income_cents:number|null;expenses_cents:number|null;other_expenses_cents:number|null;client_paid:boolean|null;event_date:string|null;deleted_at?:string|null;status?:string};
export function eventMoney(e:MoneyEvent){const income=e.income_cents??0,cost=(e.expenses_cents??0)+(e.other_expenses_cents??0);return {income,cost,profit:income-cost,margin:income>0?(income-cost)/income*100:null};}
export function moneyTotals(events:MoneyEvent[]){const total=events.reduce((a,e)=>{const m=eventMoney(e);a.income+=m.income;a.cost+=m.cost;a.paid+=e.client_paid===true?m.income:0;a.pending+=e.client_paid===false?m.income:0;a.unknown+=e.client_paid===null?m.income:0;a.incomplete+=e.income_cents===null||e.expenses_cents===null||e.other_expenses_cents===null?1:0;return a},{income:0,cost:0,paid:0,pending:0,unknown:0,incomplete:0});return {...total,profit:total.income-total.cost,margin:total.income>0?(total.income-total.cost)/total.income*100:null};}
export const euros=(cents:number)=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(cents/100);
